VALUES(
    'ai-formation.batch-02.practice-catalog.seed','02','practice-catalog.seed','1.0.0',
    '9676925ee02925076dbd97fe074d778d8c0c4a9bdd0def4ea19e72ef84fc730f','PRODUCT_DEFAULT','theology_review','["adult"]'::jsonb,
    '{"catalog_id":"ai-formation.adult-self-governance.v1","practices":[{"authority_level":"THEOLOGICAL_INFERENCE","category":"grace_anchor","difficulty":"gentle","id":"grace.identity-before-performance","minimum_action_zh":"用一句话提醒自己：操练是回应恩典，不是赚取接纳。","review_status":"theology_review","schedule":"daily","title_zh":"在操练前重申恩典身份"},{"authority_level":"PASTORAL_WISDOM","category":"attention","difficulty":"standard","id":"attention.morning-first-30","minimum_action_zh":"至少先用5分钟祷告、读经或安静，再打开信息流。","review_status":"pastoral_review","schedule":"daily","title_zh":"起床后前30分钟不进入算法信息流"},{"authority_level":"PRODUCT_DEFAULT","category":"attention","difficulty":"gentle","id":"attention.phone-away-prayer","minimum_action_zh":"将手机翻面并放到伸手够不到的位置5分钟。","review_status":"pastoral_review","schedule":"daily","title_zh":"祷告与读经时设备离手"},{"authority_level":"PASTORAL_WISDOM","category":"attention","difficulty":"gentle","id":"attention.single-task-20","minimum_action_zh":"关闭一个干扰源，专注5分钟完成当前任务。","review_status":"pastoral_review","schedule":"daily","title_zh":"20分钟单任务"},{"authority_level":"PRODUCT_DEFAULT","category":"digital_boundary","difficulty":"standard","id":"attention.notification-batch","minimum_action_zh":"先关闭一个非必要通知类别。","review_status":"pastoral_review","schedule":"daily","title_zh":"通知集中处理"},{"authority_level":"PASTORAL_WISDOM","category":"digital_boundary","difficulty":"gentle","id":"attention.intent-before-unlock","minimum_action_zh":"每次解锁前停一秒，回答“我现在要做什么”。","review_status":"pastoral_review","schedule":"triggered","title_zh":"解锁前说出目的"},{"authority_level":"PASTORAL_WISDOM","category":"attention","difficulty":"gentle","id":"attention.silence-5","minimum_action_zh":"一分钟不播放、不滚动、不切换内容。","review_status":"pastoral_review","schedule":"daily","title_zh":"五分钟无输入安静"},{"authority_level":"PASTORAL_WISDOM","category":"prayer_and_scripture","difficulty":"standard","id":"attention.long-reading-15","minimum_action_zh":"连续读一页，不切换应用。","review_status":"theology_review","schedule":"daily","title_zh":"连续阅读十五分钟"},{"authority_level":"PRODUCT_DEFAULT","category":"digital_boundary","difficulty":"gentle","id":"digital.meal-device-free","minimum_action_zh":"先完成一顿饭的前十分钟无设备。","review_status":"pastoral_review","schedule":"daily","title_zh":"一餐无设备"},{"authority_level":"PRODUCT_DEFAULT","category":"digital_boundary","difficulty":"standard","id":"digital.bedroom-charge-outside","minimum_action_zh":"睡前十五分钟把设备放到离床更远的位置。","review_status":"pastoral_review","schedule":"daily","title_zh":"设备在卧室外充电"},{"authority_level":"PRODUCT_DEFAULT","category":"digital_boundary","difficulty":"standard","id":"digital.social-window","minimum_action_zh":"今天只取消一次无目的打开。","review_status":"pastoral_review","schedule":"daily","title_zh":"社交媒体使用窗口"},{"authority_level":"PASTORAL_WISDOM","category":"digital_sabbath","difficulty":"gentle","id":"digital.sabbath-two-hours","minimum_action_zh":"先安排连续六十分钟放下非必要屏幕。","review_status":"theology_review","schedule":"weekly","title_zh":"两小时数字安息"},{"authority_level":"PASTORAL_WISDOM","category":"digital_sabbath","difficulty":"stretch","id":"digital.sabbath-half-day","minimum_action_zh":"若半天不适合，改为两小时并保留紧急例外。","review_status":"theology_review","schedule":"weekly","title_zh":"半天数字安息"},{"authority_level":"PASTORAL_WISDOM","category":"sleep_and_rest","difficulty":"standard","id":"body.sleep-window","minimum_action_zh":"今晚只把上床时间提前或稳定十分钟。","review_status":"pastoral_review","schedule":"daily","title_zh":"稳定睡眠窗口"},{"authority_level":"PRODUCT_DEFAULT","category":"sleep_and_rest","difficulty":"gentle","id":"body.wind-down-30","minimum_action_zh":"睡前十分钟停止短视频和激烈争论。","review_status":"pastoral_review","schedule":"daily","title_zh":"睡前降刺激"},{"authority_level":"PASTORAL_WISDOM","category":"movement_and_outdoors","difficulty":"gentle","id":"body.walk-20","minimum_action_zh":"步行五分钟，按身体状况调整。","review_status":"pastoral_review","schedule":"daily","title_zh":"二十分钟步行"},{"authority_level":"PASTORAL_WISDOM","category":"movement_and_outdoors","difficulty":"gentle","id":"body.outdoors-morning","minimum_action_zh":"到户外或窗边停留数分钟。","review_status":"pastoral_review","schedule":"daily","title_zh":"白天到户外"},{"authority_level":"PASTORAL_WISDOM","category":"meal_rhythm","difficulty":"standard","id":"body.meal-rhythm","minimum_action_zh":"今天先确认一餐有稳定时间。","review_status":"pastoral_review","schedule":"daily","title_zh":"规律饮食而非情绪性跳餐"},{"authority_level":"PASTORAL_WISDOM","category":"non_food_fasting","difficulty":"standard","id":"fasting.non-food-social-12h","minimum_action_zh":"先暂停一个非必要内容类别两小时。","review_status":"theology_review","schedule":"weekly","title_zh":"十二小时非食物禁食"},{"authority_level":"PASTORAL_WISDOM","category":"food_fasting","difficulty":"stretch","id":"fasting.food-one-meal-adult-cleared","minimum_action_zh":"若有任何不确定，不实行食物禁食，改用非食物禁食。","review_status":"pastoral_review","schedule":"custom","title_zh":"成人安全门后的单餐食物禁食"},{"authority_level":"PASTORAL_WISDOM","category":"delay_gratification","difficulty":"gentle","id":"delay.urge-ten-minutes","minimum_action_zh":"先延迟两分钟并离开触发界面。","review_status":"pastoral_review","schedule":"triggered","title_zh":"冲动出现时延迟十分钟"},{"authority_level":"PRODUCT_DEFAULT","category":"delay_gratification","difficulty":"standard","id":"delay.purchase-72h","minimum_action_zh":"先把物品放入清单，不立即付款。","review_status":"pastoral_review","schedule":"triggered","title_zh":"非必要购买等待72小时"},{"authority_level":"PRODUCT_DEFAULT","category":"delay_gratification","difficulty":"gentle","id":"delay.content-queue","minimum_action_zh":"不立刻观看，把一个内容移到稍后。","review_status":"pastoral_review","schedule":"triggered","title_zh":"内容进入稍后清单"},{"authority_level":"PASTORAL_WISDOM","category":"delay_gratification","difficulty":"gentle","id":"delay.boredom-five","minimum_action_zh":"等待一分钟，不马上寻找刺激。","review_status":"pastoral_review","schedule":"daily","title_zh":"五分钟承受无聊"},{"authority_level":"PASTORAL_WISDOM","category":"emotional_pause","difficulty":"gentle","id":"pause.anger","minimum_action_zh":"暂停发送，命名情绪，并等待两分钟。","review_status":"pastoral_review","schedule":"triggered","title_zh":"怒气中的暂停协议"},{"authority_level":"PASTORAL_WISDOM","category":"emotional_pause","difficulty":"gentle","id":"pause.doomscroll","minimum_action_zh":"关屏、站起、说出下一步要做的事。","review_status":"pastoral_review","schedule":"triggered","title_zh":"刷屏中的暂停协议"},{"authority_level":"PASTORAL_WISDOM","category":"emotional_pause","difficulty":"standard","id":"pause.sexual-urge-public-space","minimum_action_zh":"把设备移到公共区域并联系可信任的人。","review_status":"pastoral_review","schedule":"triggered","title_zh":"性冲动时离开隐秘设备情境"},{"authority_level":"PASTORAL_WISDOM","category":"online_speech","difficulty":"gentle","id":"speech.draft-and-wait","minimum_action_zh":"不立即发送，至少等待五分钟。","review_status":"theology_review","schedule":"triggered","title_zh":"高情绪内容先草拟后等待"},{"authority_level":"PASTORAL_WISDOM","category":"online_speech","difficulty":"gentle","id":"speech.verify-before-share","minimum_action_zh":"若无法确认来源，今天先不转发。","review_status":"theology_review","schedule":"triggered","title_zh":"转发前核实"},{"authority_level":"PASTORAL_WISDOM","category":"online_speech","difficulty":"standard","id":"speech.direct-conversation","minimum_action_zh":"先写下要面对面表达的一句事实。","review_status":"pastoral_review","schedule":"triggered","title_zh":"用直接沟通替代公开羞辱"},{"authority_level":"THEOLOGICAL_INFERENCE","category":"service","difficulty":"standard","id":"comfort.inconvenient-service","minimum_action_zh":"完成一个不被看见的五分钟帮助。","review_status":"theology_review","schedule":"weekly","title_zh":"一项不方便但有爱的服事"},{"authority_level":"PASTORAL_WISDOM","category":"responsibility","difficulty":"gentle","id":"comfort.complete-hard-task","minimum_action_zh":"对最想逃避的责任投入五分钟。","review_status":"pastoral_review","schedule":"daily","title_zh":"先完成一项困难责任"},{"authority_level":"PASTORAL_WISDOM","category":"responsibility","difficulty":"standard","id":"comfort.stay-present-conversation","minimum_action_zh":"放下手机，完整听完对方两分钟；危险关系除外。","review_status":"pastoral_review","schedule":"triggered","title_zh":"在困难谈话中保持在场"},{"authority_level":"THEOLOGICAL_INFERENCE","category":"service","difficulty":"gentle","id":"service.unseen-good","minimum_action_zh":"今天完成一个不发布、不展示的小善行。","review_status":"theology_review","schedule":"weekly","title_zh":"做一件无人知道的善事"},{"authority_level":"PASTORAL_WISDOM","category":"prayer_and_scripture","difficulty":"gentle","id":"prayer.psalm-slow-read","minimum_action_zh":"慢读两节并用自己的话回应神。","review_status":"theology_review","schedule":"daily","title_zh":"慢读一段诗篇"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_02/assets/practice-catalog.seed.yaml","sha256":"9676925ee02925076dbd97fe074d778d8c0c4a9bdd0def4ea19e72ef84fc730f","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
) ON CONFLICT (id,version) DO NOTHING;

