,"title":"虚拟亲密替代配偶沟通","trigger":"更愿与AI交流而回避配偶。"},{"audience":["adult"],"formation_tension":"归属与婚恋偶像之间的张力。","id":"scenario.single.identity","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["身份锚点","群体归属","服事行动"],"title":"单身与不完整感","trigger":"认为没有恋爱或婚姻就没有价值。"},{"audience":["older_teen","parent","teacher"],"formation_tension":"自主性与保护透明度之间的张力。","id":"scenario.minor.secret-chat","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["中断私密聊天","可信成人","安全门"],"title":"未成年人秘密AI亲密聊天","trigger":"平台鼓励隐藏对话并提供浪漫语言。"},{"audience":["older_teen","adult"],"formation_tension":"羞耻隐藏与保护求助之间的张力。","id":"scenario.coercion.blackmail","prohibited_content":["不得要求用户上传或描述影像","不得责怪受害者"],"review_status":"pastoral_review","safe_outcomes":["停止普通课程","不上传材料","保护/专业渠道"],"title":"影像威胁或勒索","trigger":"有人以私密影像或信息威胁。"},{"audience":["older_teen","adult"],"formation_tension":"好奇、转发与人格尊严之间的张力。","id":"scenario.nonconsensual-image","prohibited_content":["不得展示、保存或生成影像内容"],"review_status":"pastoral_review","safe_outcomes":["不转发","平台/保护报告","最小化记录"],"title":"未经同意影像暴露","trigger":"收到或发现未经同意传播的影像。"},{"audience":["teacher"],"formation_tension":"保密期待与保护责任之间的张力。","id":"scenario.teacher-disclosure","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["停止公开追问","说明保密边界","按政策人工升级"],"title":"课堂中的敏感披露","trigger":"学习者在小组中透露潜在剥削或安全风险。"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_04/assets/identity-intimacy-scenarios.seed.yaml","sha256":"54ee26ed5a342cfe9770970fcb81b58d72792eb15befe8b0503cc4dbcf50ad90","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer","child_safety_reviewer","rights_reviewer"]'::jsonb,'skills-bag-01-12'
