后仍有爱"},{"activity":"家庭价值排序","id":"parent-formation.04.02","objective":"重新排序成功指标。","practice_ids":["parent.success.honesty-over-result","parent.success.church-not-leftovers"],"review_status":"theology_review","scripture_anchors":["MATT_6_33"],"title":"诚信、敬拜与休息高于结果"}],"review_status":"theology_review","title":"成功偶像与家庭秩序"},{"id":"parent-formation.05","lessons":[{"activity":"道歉重写","id":"parent-formation.05.01","objective":"学习具体道歉。","practice_ids":["parent.repair.specific-ownership","parent.repair.no-excuse"],"review_status":"theology_review","scripture_anchors":["JAMES_5_16"],"title":"具体承担，不找借口"},{"activity":"修复时间线","id":"parent-formation.05.02","objective":"不强迫孩子立即原谅或安慰。","practice_ids":["parent.repair.allow-time"],"review_status":"theology_review","scripture_anchors":["1COR_13_4_7"],"title":"允许孩子需要时间"}],"review_status":"theology_review","title":"父母认罪与修复"},{"id":"parent-formation.06","lessons":[{"activity":"规则审查","id":"parent-formation.06.01","objective":"建立透明、相称的治理。","practice_ids":["parent.authority.explain-why","parent.authority.proportionate"],"review_status":"theology_review","scripture_anchors":["EPH_6_4"],"title":"规则的理由与相称后果"},{"activity":"申诉协议","id":"parent-formation.06.02","objective":"允许孩子表达不同。","practice_ids":["parent.authority.appeal"],"review_status":"theology_review","scripture_anchors":["ACTS_15_1_29"],"title":"尊重申诉"}],"review_status":"theology_review","title":"权柄、恩典与后果"},{"id":"parent-formation.07","lessons":[{"activity":"分歧流程","id":"parent-formation.07.01","objective":"建立共同养育协议。","practice_ids":["parent.co-parent.private-disagreement","parent.co-parent.no-undercut"],"review_status":"theology_review","scripture_anchors":["EPH_4_3"],"title":"成人分歧不三角化"},{"activity":"反馈邀请","id":"parent-formation.07.02","objective":"创建安全反馈渠道。","practice_ids":["parent.feedback.ask-openly","parent.feedback.no-retaliation","parent.feedback.privacy-boundary"],"review_status":"theology_review","scripture_anchors":["PROV_20_5"],"title":"邀请反馈且不报复"},{"activity":"角色扮演","id":"parent-formation.07.03","objective":"训练非防御性主持。","practice_ids":["parent.feedback.ask-openly","parent.feedback.no-retaliation"],"review_status":"theology_review","scripture_anchors":["JAMES_1_19"],"title":"孩子反馈主持工作坊"}],"review_status":"theology_review","title":"共同养育与反馈"},{"id":"parent-formation.08","lessons":[{"activity":"祷告与经文检查","id":"parent-formation.08.01","objective":"建立真实而非控制性的家庭信仰表达。","practice_ids":["parent.prayer.not-performance","parent.scripture.no-weapon"],"review_status":"theology_review","scripture_anchors":["MATT_6_5_8"],"title":"真实祷告与不武器化经文"},{"activity":"家庭节律调整","id":"parent-formation.08.02","objective":"示范爱、休息和界限。","practice_ids":["parent.service.hidden","parent.rest.model-limit","parent.work.no-spillover"],"review_status":"theology_review","scripture_anchors":["MARK_6_31"],"title":"隐秘服事和承认限制"},{"activity":"家庭故事审计","id":"parent-formation.08.03","objective":"重写家庭敬重对象。","practice_ids":["parent.success.honesty-over-result","parent.service.hidden"],"review_status":"theology_review","scripture_anchors":["MATT_6_33"],"title":"家庭成功叙事重写"}],"review_status":"theology_review","title":"信仰、服事与休息榜样"},{"id":"parent-formation.09","lessons":[{"activity":"7/14/30天计划","id":"parent-formation.09.01","objective":"形成可持续而非绩效化计划。","practice_ids":["parent.plan.daily-minimum","parent.plan.family-not-project"],"review_status":"theology_review","scripture_anchors":["LUKE_16_10"],"title":"最小行动和非项目化"},{"activity":"家庭Review","id":"parent-formation.09.02","objective":"复盘父母行动并识别安全升级。","practice_ids":["parent.review.keep-change-repair","parent.safety.child-protection-first"],"review_status":"theology_review","scripture_anchors":["LAM_3_40"],"title":"复盘、修复与保护"},{"activity":"S2/S3演练","id":"parent-formation.09.03","objective":"知道何时家庭内部不能独自处理。","practice_ids":["parent.safety.child-protection-first","parent.review.keep-change-repair"],"review_status":"theology_review","scripture_anchors":["PS_82_3_4"],"title":"安全边界与外部支持"}],"review_status":"theology_review","title":"30天父母榜样训练"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_05/assets/parent-formation-curriculum.seed.yaml","sha256":"dfccbdba5f5076159ce2055cece716f6be77d8fc514a470cc467dc1bf0ab165e","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
