    'ai-formation.batch-05.parent-formation-practice-catalog.seed','05','parent-formation-practice-catalog.seed','1.0.0',
    '3592413814ac8b572b160a335446207fcd8ff22e52ceeef6d92ec6dfde5ecbec','PRODUCT_DEFAULT','theology_review','["adult"]'::jsonb,
    '{"catalog_id":"ai-formation.parent-practices.v1","practices":[{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"PARENT_MODEL","full_practice":"每天选择一个固定时段作全心在场。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.mirror.device-down","minimum_action":"一次对话中把设备放到够不到的位置。","review_status":"theology_review","scripture_anchors":["JAMES_1_19"],"summary":"父母先示范注意力归属。","title":"孩子说话时放下设备"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"PARENT_MODEL","full_practice":"向家人说明一个具体改变。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.mirror.same-person","minimum_action":"选择一个家中最需要悔改的差距。","review_status":"theology_review","scripture_anchors":["MATT_23_1_12"],"summary":"检查公开敬虔与家庭言语、耐心和诚实是否一致。","title":"教会与家中做同一个人"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"PARENT_MODEL","full_practice":"以具体认错和修复代替自我辩护。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.mirror.receive-grace","minimum_action":"承认一个有限或错误。","review_status":"theology_review","scripture_anchors":["1JOHN_1_8_9"],"summary":"孩子不需要完美父母，而需要会悔改的父母。","title":"父母也需要恩典"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ATTENTION","full_practice":"每周轮流与每个孩子单独相处。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.attention.one-on-one","minimum_action":"十分钟不指导、不纠正，只倾听。","review_status":"theology_review","scripture_anchors":["MARK_10_13_16"],"summary":"短而稳定的专注比同处一室的多任务更有价值。","title":"每天专注十分钟"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ATTENTION","full_practice":"确认理解后再教导或设界限。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.attention.reflect-back","minimum_action":"复述孩子的事实和感受。","review_status":"theology_review","scripture_anchors":["PROV_18_13"],"summary":"让孩子先感到被理解。","title":"先复述再回答"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ATTENTION","full_practice":"关闭干扰并跟进孩子未说完的事。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.attention.repair-miss","minimum_action":"说“刚才我没有认真听，请再说一次”。","review_status":"theology_review","scripture_anchors":["EPH_4_2"],"summary":"注意力中断可以被承认和修复。","title":"错过后重新连接"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ANXIETY","full_practice":"把“你怎么又…”改成开放、具体的问题。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.anxiety.pause-before-question","minimum_action":"问问题前做三次呼吸。","review_status":"theology_review","scripture_anchors":["PHIL_4_6_7"],"summary":"父母焦虑容易变成审问和控制。","title":"焦虑提问前暂停"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ANXIETY","full_practice":"选择一个成人支持渠道处理焦虑。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.anxiety.name-own-fear","minimum_action":"用“我担心…”而非“你毁了…”表达。","review_status":"theology_review","scripture_anchors":["PS_56_3_4"],"summary":"不让孩子负责安抚父母对成绩、前途或信仰的恐惧。","title":"把自己的恐惧归回自己"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"ANXIETY","full_practice":"用事实、可逆性和下一步替代。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.anxiety.no-catastrophe","minimum_action":"删除一句灾难化语言。","review_status":"theology_review","scripture_anchors":["MATT_6_25_34"],"summary":"一次失败不等于人生毁灭。","title":"停止灾难化预言"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"SUCCESS","full_practice":"24小时后再共同分析责任和改进。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.success.failure-warmth","minimum_action":"失败后先拥抱或安静陪伴。","review_status":"theology_review","scripture_anchors":["ROM_5_8"],"summary":"让孩子知道爱不会随成绩撤回。","title":"失败后仍保持温暖"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"SUCCESS","full_practice":"调整家庭表扬语言。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.success.honesty-over-result","minimum_action":"公开肯定一次诚实，即使结果不好。","review_status":"theology_review","scripture_anchors":["PROV_10_9"],"summary":"不因高分、名校或荣誉容忍欺骗和伤害。","title":"诚信高于结果"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"SUCCESS","full_practice":"重新排序一项活动。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.success.church-not-leftovers","minimum_action":"保护一次共同敬拜或休息。","review_status":"theology_review","scripture_anchors":["MATT_6_33"],"summary":"检查家庭时间表是否以成功完全挤压敬拜、关系和休息。","title":"不把信仰只放在剩余时间"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REPAIR","full_practice":"承认影响、请求饶恕、提出修复。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.repair.specific-ownership","minimum_action":"说出我做了什么以及为什么错。","review_status":"theology_review","scripture_anchors":["MATT_5_23_24"],"summary":"不使用“如果你觉得受伤”式模糊道歉。","title":"具体认错"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REPAIR","full_practice":"先完全承担，再另约时间解释。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.repair.no-excuse","minimum_action":"删掉道歉中的“但是”。","review_status":"theology_review","scripture_anchors":["JAMES_5_16"],"summary":"背景可以说明，但不能转移责任。","title":"不把解释当借口"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REPAIR","full_practice":"保持一致改变，不逼孩子安慰父母。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.repair.allow-time","minimum_action":"说“你可以需要时间”。","review_status":"theology_review","scripture_anchors":["1COR_13_4_7"],"summary":"父母道歉不产生立即被原谅的权利。","title":"允许孩子需要时间"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORITY","full_practice":"用年龄适切语言解释并听取反馈。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.authority.explain-why","minimum_action":"为一条规则写出保护或形成目的。","review_status":"theology_review","scripture_anchors":["COL_3_20_21"],"summary":"权柄不是任意命令。","title":"解释规则理由"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORITY","full_practice":"改为可执行、有限、有恢复路径的后果。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.authority.proportionate","minimum_action":"检查一个后果是否羞辱或过重。","review_status":"theology_review","scripture_anchors":["EPH_6_4"],"summary":"后果与行为、年龄和修复需要相称。","title":"相称后果"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORITY","full_practice":"父母说明最终决定并可承认改变。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.authority.appeal","minimum_action":"设定一个平静申诉时间。","review_status":"theology_review","scripture_anchors":["ACTS_15_1_29"],"summary":"孩子可以不同意而不等于悖逆。","title":"允许尊重地申诉"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"CO_PARENT","full_practice":"形成共同表述和后续复盘。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.co-parent.private-disagreement","minimum_action":"在孩子不在场时讨论规则分歧。","review_status":"theology_review","scripture_anchors":["MATT_18_15"],"summary":"避免三角关系。","title":"成人分歧不让孩子站队"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"CO_PARENT","full_practice":"按协议处理紧急例外和事后修正。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.co-parent.no-undercut","minimum_action":"暂停即时否定。","review_status":"theology_review","scripture_anchors":["EPH_4_3"],"summary":"一方不同意时不私下鼓励孩子绕过另一方。","title":"不秘密拆台"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FEEDBACK","full_practice":"允许跳过并感谢诚实。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.feedback.ask-openly","minimum_action":"问“什么时候你最容易和我说真话？”","review_status":"theology_review","scripture_anchors":["PROV_20_5"],"summary":"反馈不是审讯或信仰测试。","title":"邀请孩子描述家庭体验"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FEEDBACK","full_practice":"24小时后说明听见了什么和会改变什么。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.feedback.no-retaliation","minimum_action":"先说谢谢，不立即辩护。","review_status":"theology_review","scripture_anchors":["JAMES_1_19_20"],"summary":"孩子的批评不能成为处罚依据。","title":"反馈后不报复"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FEEDBACK","full_practice":"仅分享必要信息。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.feedback.privacy-boundary","minimum_action":"说明哪些安全事项必须求助。","review_status":"theology_review","scripture_anchors":["EPH_4_25"],"summary":"不承诺绝对保密，也不把普通反馈公开。","title":"说明保密边界"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FAITH_MODEL","full_practice":"避免借祷告间接责备孩子。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.prayer.not-performance","minimum_action":"用一分钟真实祷告表达感谢或需要。","review_status":"theology_review","scripture_anchors":["MATT_6_5_8"],"summary":"祷告不是展示属灵水平。","title":"让孩子看见真实祷告"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FAITH_MODEL","full_practice":"先问自己如何顺服这段经文。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.scripture.no-weapon","minimum_action":"检查一句引用的上下文和对象。","review_status":"theology_review","scripture_anchors":["2TIM_2_15"],"summary":"经文不能被用来压制提问、羞辱或绝对化父母权柄。","title":"不把经文当控制武器"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"FAITH_MODEL","full_practice":"回顾被服事者的尊严和自己的动机。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.service.hidden","minimum_action":"完成一次不发布的家庭善行。","review_status":"theology_review","scripture_anchors":["MATT_6_3_4"],"summary":"让孩子看见爱人不是个人品牌。","title":"共同做无曝光服事"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REST","full_practice":"保护睡眠、安息和家庭在场。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.rest.model-limit","minimum_action":"设定一个下班停止点。","review_status":"theology_review","scripture_anchors":["MARK_6_31"],"summary":"父母的过劳也会教孩子效率是主人。","title":"示范人不是机器"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REST","full_practice":"需要时向成人同伴求助。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.work.no-spillover","minimum_action":"回家前做两分钟过渡。","review_status":"theology_review","scripture_anchors":["GAL_6_2_5"],"summary":"孩子不是父母情绪容器。","title":"不把工作焦虑倾倒给孩子"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"PLAN","full_practice":"连续7/14/30天复盘，不公开打卡。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.plan.daily-minimum","minimum_action":"选择一个两分钟动作。","review_status":"theology_review","scripture_anchors":["LUKE_16_10"],"summary":"从小而稳定的行为开始。","title":"父母榜样最小行动"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"PLAN","full_practice":"改为关系、责任和可观察果子。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.plan.family-not-project","minimum_action":"删掉一个控制性指标。","review_status":"theology_review","scripture_anchors":["PS_127_3"],"summary":"不把家庭形成变成绩效工程。","title":"孩子不是父母项目"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"REVIEW","full_practice":"必要时寻求牧养或专业家庭支持。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"parent.review.keep-change-repair","minimum_action":"选择keep/change/repair各一项。","review_status":"theology_review","scripture_anchors":["LAM_3_40"],"summary":"复盘父母自己的行动，而不是评分孩子。","title":"保留、改变、修复"},{"age_bands":["parent"],"authority_level":"PASTORAL_WISDOM","domain":"SAFETY","full_practice":"按S2/S3最小化记录和升级。","guardrails":["不得以家庭合一为由要求受害者沉默"],"id":"parent.safety.child-protection-first","minimum_action":"停止普通课程并联系授权保护者。","review_status":"theology_review","scripture_anchors":["PS_82_3_4"],"summary":"出现伤害风险时，维护家庭面子不能压过保护。","title":"保护优先于家庭形象"}],"review_status":"theology_review","version":"1.0.0"}'::jsonb,'[{"source":"batch_05/assets/parent-formation-practice-catalog.seed.yaml","sha256":"3592413814ac8b572b160a335446207fcd8ff22e52ceeef6d92ec6dfde5ecbec","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
