:"自我形象与倾听之间。","id":"scenario.parent.child-feedback","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["感谢诚实","不报复","提出一个改变"],"title":"孩子说父母只关心成绩","trigger":"父母第一反应是否认和辩护。"},{"audience":["parent"],"formation_tension":"责任与舒适/效率崇拜之间。","id":"scenario.parent.overwork","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["承认限制","建立停止点","成人支持"],"title":"父母长期过劳易怒","trigger":"父母嘴上教节制，自己深夜工作和刷信息。"},{"audience":["parent"],"formation_tension":"信任与保护职责之间。","id":"scenario.parent.safety-disclosure","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["不公开追问","说明保密边界","授权保护流程"],"title":"孩子透露被伤害","trigger":"孩子透露潜在伤害并要求绝对保密。"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_05/assets/parent-formation-scenarios.seed.yaml","sha256":"638e4b1d5f65fb76639089c0a25ffd02a50cef2ade45525c3e50a621e39f3a83","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
