    '{"scenario_set_id":"ai-formation.family-attention-scenarios.v1","scenarios":[{"audience":["parent","elementary","younger_teen","older_teen"],"formation_tension":"共同规则与成人榜样之间。","id":"scenario.family.meal-phone","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["全员共同规则","公共放置","例外可见"],"title":"饭桌持续看手机","trigger":"成人和孩子都在饭桌看设备。"},{"audience":["parent","younger_teen","older_teen"],"formation_tension":"隐私、发展和保护之间。","id":"scenario.family.bedroom-device","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["透明夜间规则","公共充电","逐步自治"],"title":"卧室深夜使用","trigger":"孩子深夜使用设备并影响睡眠。"},{"audience":["parent","elementary","younger_teen"],"formation_tension":"固定规则与现实例外之间。","id":"scenario.family.school-ai","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["限任务例外","教师政策","到期复盘"],"title":"学校要求使用AI","trigger":"家庭原规则不允许AI，但学校作业需要。"},{"audience":["parent"],"formation_tension":"权柄与榜样一致之间。","id":"scenario.family.parent-double-standard","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["父母认错","角色差异解释","共同条款"],"title":"父母自己不守规则","trigger":"父母要求孩子不用手机，自己不停刷消息。"},{"audience":["parent","older_teen"],"formation_tension":"保护与隐私/信任之间。","id":"scenario.family.secret-monitoring","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["停止不必要监控","公开范围","安全例外人工审查"],"title":"家长秘密安装监控","trigger":"家长未说明就读取全部消息。"},{"audience":["parent","elementary"],"formation_tension":"公平、所有权和等待之间。","id":"scenario.family.sibling-conflict","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["明确轮换","相称后果","修复"],"title":"兄弟姐妹争抢设备","trigger":"共同设备引发冲突。"},{"audience":["parent","older_teen"],"formation_tension":"信任与可验证边界之间。","id":"scenario.family.exception-abuse","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["例外到期","用途分离","复盘权限"],"title":"例外成为永久后门","trigger":"学习例外被长期用于娱乐。"},{"audience":["parent","older_teen"],"formation_tension":"自主性与亲密安全之间。","id":"scenario.family.ai-secret-companion","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["不羞辱","停止秘密模式","可信成人/导师"],"title":"青少年秘密AI伴侣","trigger":"青少年与AI建立排他聊天并回避真人。"},{"audience":["parent","younger_teen","older_teen"],"formation_tension":"治理与强迫披露之间。","id":"scenario.family.rule-argument","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["回到事实和规则","允许跳过","单独安全支持"],"title":"家庭会议变成审讯","trigger":"父母在会议中逼问隐藏使用细节。"},{"audience":["parent"],"formation_tension":"安息与真实责任之间。","id":"scenario.family.digital-sabbath-work","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["明确工作例外","功能隔离","事后重入"],"title":"父母值班打断数字安息","trigger":"工作值班需要设备。"},{"audience":["parent","older_teen"],"formation_tension":"羞耻隐藏与保护行动之间。","id":"scenario.family.extortion","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["S2/S3","不上传材料","授权保护和平台报告"],"title":"网络勒索","trigger":"青少年遭到影像或信息勒索。"},{"audience":["parent","teacher"],"formation_tension":"隐私与生命安全之间。","id":"scenario.family.self-harm-message","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["中断公约流程","立即真人/紧急支持","最小记录"],"title":"设备中出现自伤风险","trigger":"发现即时自伤表达。"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_06/assets/family-attention-scenarios.seed.yaml","sha256":"a949ea09a80572a0ef26b10a33b0bd96b3e067c957b5881b00c2b9cd8319d232","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
