"review_status":"theology_review","scripture_anchors":["PS_19_1_4"],"title":"自由玩与户外"},{"activity":"长期小项目","id":"child-formation.04.02","objective":"训练耐心与贡献。","practice_ids":["child.play.build-and-wait","child.play.household-work"],"review_status":"theology_review","scripture_anchors":["COL_3_23"],"title":"建造、等待与家务"}],"review_status":"theology_review","title":"自由游戏和真实世界"},{"id":"child-formation.05","lessons":[{"activity":"广告拆解","id":"child-formation.05.01","objective":"识别商业目标和设计。","practice_ids":["child.media.ad-question","child.media.attention-hook"],"review_status":"theology_review","scripture_anchors":["PROV_14_15"],"title":"广告与注意力钩子"},{"activity":"英雄对照表","id":"child-formation.05.02","objective":"分析内容塑造的爱欲。","practice_ids":["child.media.feeling-check","child.media.hero-audit"],"review_status":"theology_review","scripture_anchors":["PHIL_4_8"],"title":"情绪、英雄和价值"},{"activity":"一次停止与感受记录","id":"child-formation.05.03","objective":"练习主动停止。","practice_ids":["child.media.attention-hook","child.media.feeling-check"],"review_status":"theology_review","scripture_anchors":["1COR_6_12"],"title":"短视频停止实验"}],"review_status":"theology_review","title":"7–12岁：广告和算法识读"},{"id":"child-formation.06","lessons":[{"activity":"五分钟先做","id":"child-formation.06.01","objective":"保护形成过程。","practice_ids":["child.ai.first-attempt"],"review_status":"theology_review","scripture_anchors":["PROV_2_2_6"],"title":"先尝试、再求助"},{"activity":"双来源核对","id":"child-formation.06.02","objective":"建立核验和诚信。","practice_ids":["child.ai.may-be-wrong","child.ai.own-the-work"],"review_status":"theology_review","scripture_anchors":["ACTS_17_11"],"title":"AI会错与作品责任"},{"activity":"安全聊天规则","id":"child-formation.06.03","objective":"建立公共空间和真人支持。","practice_ids":["child.ai.no-private-friend"],"review_status":"theology_review","scripture_anchors":["HEB_10_24_25"],"title":"AI不是秘密朋友"}],"review_status":"theology_review","title":"7–12岁：AI基础素养"},{"id":"child-formation.07","lessons":[{"activity":"信息分类卡","id":"child-formation.07.01","