与保护流程"},{"activity":"家庭周回顾","id":"child-formation.10.03","objective":"把课程带回日常。","practice_ids":["child.rhythm.meal-gratitude","child.responsibility.small-contribution"],"review_status":"theology_review","scripture_anchors":["DEUT_6_6_7"],"title":"家庭共同复盘"}],"review_status":"theology_review","title":"身体边界和保护"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_07/assets/child-formation-curriculum.seed.yaml","sha256":"cbb4ed8590ebe5d0185fb42b9de36cad9217467291cb52c129b0c73cd1d5aa23","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer","child_safety_reviewer","accessibility_reviewer"]'::jsonb,'skills-bag-01-12'
