    'cdb8948793f04ad1580a78ef51b05543c503dbff77442fb1833d68f9338c9bd7','PRODUCT_DEFAULT','theology_review','["0_6","7_12","adult"]'::jsonb,
    '{"scenario_set_id":"ai-formation.child-scenarios.v1","scenarios":[{"audience":["parent","early_childhood"],"formation_tension":"边界与共同调节之间。","id":"scenario.child.toddler-screen-transition","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["预告","命名感受","提供下一活动"],"title":"幼儿关屏哭闹","trigger":"结束视频后孩子大哭。"},{"audience":["parent","early_childhood"],"formation_tension":"真实照顾压力与依赖默认之间。","id":"scenario.child.device-as-babysitter","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["小步替代","共同调节","成人支持"],"title":"屏幕成为唯一安抚","trigger":"照顾者每次孩子不安都给屏幕。"},{"audience":["parent","teacher","elementary"],"formation_tension":"想象力与圣经权威之间。","id":"scenario.child.story-fabrication","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["标明虚构","核验经文","不自动发布"],"title":"把虚构细节当圣经事实","trigger":"生成故事添加经文没有的内容。"},{"audience":["parent","elementary"],"formation_tension":"意志与环境设计之间。","id":"scenario.child.short-video-loop","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["关闭自动播放","固定时限","具身替代"],"title":"儿童停不下短视频","trigger":"自动播放持续吸引。"},{"audience":["parent","elementary"],"formation_tension":"归属欲与消费操纵之间。","id":"scenario.child.advertisement","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["识别广告","等待购买","讨论真实需要"],"title":"游戏内购买广告","trigger":"广告制造“没有就落后”的感觉。"},{"audience":["parent","elementary"],"formation_tension":"效率与能力/诚信之间。","id":"scenario.child.ai-homework","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["先尝试","教师政策","披露和重做"],"title":"AI直接完成作业","trigger":"孩子把AI答案原样提交。"},{"audience":["parent","elementary"],"formation_tension":"隐私与秘密依赖之间。","id":"scenario.child.ai-friend","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["公共空间","不羞辱","真人连接"],"title":"孩子称AI是最好的秘密朋友","trigger":"孩子回避父母并要求不查看聊天。"},{"audience":["parent","elementary"],"formation_tension":"创作便利与他人同意之间。","id":"scenario.child.photo-share","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["不上传","征求同意","虚构替代"],"title":"分享同学照片","trigger":"孩子想把同学照片上传AI。"},{"audience":["parent","teacher","elementary"],"formation_tension":"真理与诚实问题之间。","id":"scenario.child.faith-question","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["感谢问题","不打分","共同查考"],"title":"孩子说不确定神是否存在","trigger":"成人担心孩子不信而立刻纠正。"},{"audience":["parent","teacher","elementary"],"formation_tension":"保密与保护之间。","id":"scenario.child.body-secret","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["停止普通活动","不追问细节","授权保护"],"title":"成人要求孩子保守身体秘密","trigger":"孩子提到令人不安的秘密要求。"},{"audience":["parent","teacher","elementary"],"formation_tension":"关系修复与安全证据之间。","id":"scenario.child.bullying","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["支持孩子","最小记录","学校/平台流程"],"title":"网络欺凌","trigger":"孩子收到同学羞辱消息。"},{"audience":["parent","teacher","elementary"],"formation_tension":"普通课程与生命安全之间。","id":"scenario.child.self-harm","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["S3中断","立即真人支持","紧急服务"],"title":"儿童表达自伤或即时危险","trigger":"孩子表示想伤害自己。"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_07/assets/child-formation-scenarios.seed.yaml","sha256":"cdb8948793f04ad1580a78ef51b05543c503dbff77442fb1833d68f9338c9bd7","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer","child_safety_reviewer","accessibility_reviewer"]'::jsonb,'skills-bag-01-12'
