    '{"course_id":"ai-formation.youth-autonomy.v1","review_status":"theology_review","units":[{"id":"youth.01","lessons":[{"activity":"身份地图","id":"youth.01.01","objective":"识别身份压力。","practice_ids":["youth.identity.received-not-curated","youth.identity.pressure-map"],"review_status":"theology_review","scripture_anchors":["COL_3_1_4"],"title":"领受身份与表演自我"},{"activity":"暂定语言练习","id":"youth.01.02","objective":"保留探索空间。","practice_ids":["youth.identity.no-label-rush"],"review_status":"theology_review","scripture_anchors":["PS_139_13_18"],"title":"不急于被标签定义"}],"review_status":"theology_review","title":"身份、压力与真实自我"},{"id":"youth.02","lessons":[{"activity":"问题拆分","id":"youth.02.01","objective":"形成可研究问题。","practice_ids":["youth.question.say-it-plainly"],"review_status":"theology_review","scripture_anchors":["MARK_9_24"],"title":"把问题说清楚"},{"activity":"来源路线","id":"youth.02.02","objective":"建立长期求真过程。","practice_ids":["youth.question.source-plan","youth.question.no-perform"],"review_status":"theology_review","scripture_anchors":["ACTS_17_11"],"title":"来源计划和允许不确定"}],"review_status":"theology_review","title":"怀疑、问题与求真"},{"id":"youth.03","lessons":[{"activity":"情境判断","id":"youth.03.01","objective":"建立尊重边界。","practice_ids":["youth.sexuality.body-dignity"],"review_status":"theology_review","scripture_anchors":["1THESS_4_3_8"],"title":"身体尊严、同意和不强迫"},{"activity":"安全退出计划","id":"youth.03.02","objective":"识别必须求助的信号。","practice_ids":["youth.sexuality.no-secret-pressure","youth.sexuality.ai-romance-boundary"],"review_status":"theology_review","scripture_anchors":["PS_82_3_4"],"title":"秘密压力、勒索和AI浪漫"}],"review_status":"theology_review","title":"身体、性与安全边界"},{"id":"youth.04","lessons":[{"activity":"形象审计","id":"youth.04.01","objective":"识别表演压力。","practice_ids":["youth.social.online-offline-gap"],"review_status":"theology_review","scripture_anchors":["EPH_4_25"],"title":"线上/线下差距"},{"activity":"一周实验","id":"youth.04.02","objective":"建立内容和发布边界。","practice_ids":["youth.social.comparison-reset","youth.social.anger-delay","youth.social.hidden-good"],"review_status":"theology_review","scripture_anchors":["JAMES_1_19_20"],"title":"比较、愤怒和隐秘善行"},{"activity":"世界观画布","id":"youth.04.03","objective":"分析网红定义的成功。","practice_ids":["youth.social.comparison-reset","youth.identity.pressure-map"],"review_status":"theology_review","scripture_anchors":["ROM_12_2"],"title":"网红与成功叙事"}],"review_status":"theology_review","title":"社交媒体身份表演"},{"id":"youth.05","lessons":[{"activity":"作业流程图","id":"youth.05.01","objective":"尊重课程政策。","practice_ids":["youth.ai.policy-first","youth.ai.minimum-attempt"],"review_status":"theology_review","scripture_anchors":["PROV_2_1_6"],"title":"政策、独立尝试和AI角色"},{"activity":"披露模板","id":"youth.05.02","objective":"承担最终作者责任。","practice_ids":["youth.ai.verify-and-revise","youth.ai.disclose-use"],"review_status":"theology_review","scripture_anchors":["ACTS_17_11"],"title":"核验、修改和披露"}],"review_status":"theology_review","title":"AI与学习诚信"},{"id":"youth.06","lessons":[{"activity":"能力规则提案","id":"youth.06.01","objective":"练习自治提案。","practice_ids":["youth.autonomy.propose-plan","youth.autonomy.ask-exception"],"review_status":"theology_review","scripture_anchors":["LUKE_16_10"],"title":"提出计划和请求例外"},{"activity":"回退恢复协议","id":"youth.06.02","objective":"让信任可恢复。","practice_ids":["youth.autonomy.disclose-error","youth.autonomy.review-not-permanent"],"review_status":"theology_review","scripture_anchors":["1JOHN_1_7"],"title":"错误、修复和临时回退"},{"activity":"权限透明表","id":"youth.06.03","objective":"讨论可见数据和边界。","practice_ids":["youth.autonomy.propose-plan","youth.autonomy.review-not-permanent"],"review_status":"theology_review","scripture_anchors":["2COR_8_21"],"title":"隐私透明与家长控制"}],"review_status":"theology_review","title":"数字自治：从共同决定到自我治理"},{"id":"youth.07","lessons":[{"activity":"一周时间图","id":"youth.07.01","objective":"保护身体和创造。","practice_ids":["youth.time.sleep-first","youth.time.unstructured"],"review_status":"theology_review","scripture_anchors":["MARK_6_31"],"title":"睡眠与无安排时间"},{"activity":"小预算练习","id":"youth.07.02","objective":"学习基本金钱责任。","practice_ids":["youth.money.give-save-spend","youth.money.subscription-audit"],"review_status":"theology_review","scripture_anchors":["2COR_9_7"],"title":"给予、储蓄、消费和订阅"}],"review_status":"theology_review","title":"时间和金钱托付"},{"id":"youth.08","lessons":[{"activity":"导师协议","id":"youth.08.01","objective":"建立透明关系。","practice_ids":["youth.mentor.safe-channel"],"review_status":"theology_review","scripture_anchors":["1TIM_5_1_2"],"title":"安全导师渠道"},{"activity":"访谈任务","id":"youth.08.02","objective":"扩展属灵榜样。","practice_ids":["youth.mentor.ask-real-question","youth.mentor.multi-generational"],"review_status":"theology_review","scripture_anchors":["TITUS_2_1_8"],"title":"真实问题和多代见证"}],"review_status":"theology_review","title":"导师和多代教会"},{"id":"youth.09","lessons":[{"activity":"里程碑评审","id":"youth.09.01","objective":"用可观察证据讨论权限。","practice_ids":["youth.transfer.evidence"],"review_status":"theology_review","scripture_anchors":["LUKE_16_10"],"title":"责任证据和下一层自治"},{"activity":"恢复条件设计","id":"youth.09.02","objective":"避免永久定罪。","practice_ids":["youth.transfer.rollback-plan"],"review_status":"theology_review","scripture_anchors":["HEB_12_11"],"title":"临时回退与恢复"}],"review_status":"theology_review","title":"逐步交还治理权"},{"id":"youth.10","lessons":[{"activity":"离家检查","id":"youth.10.01","objective":"建立实用独立支持。","practice_ids":["youth.leaving.security","youth.leaving.support-map"],"review_status":"theology_review","scripture_anchors":["ECCL_4_9_12"],"title":"账户安全和支持地图"},{"activity":"30天规则","id":"youth.10.02","objective":"整合数字与属灵生活。","practice_ids":["youth.leaving.rule-of-life"],"review_status":"theology_review","scripture_anchors":["EPH_5_15_17"],"title":"个人生活规则"},{"activity":"求助演练","id":"youth.10.03","objective":"掌握安全升级。","practice_ids":["youth.safety.no-blame","youth.safety.tell-two","youth.safety.S3-interrupt"],"review_status":"theology_review","scripture_anchors":["PROV_24_11"],"title":"危险中求助而不自责"},{"activity":"毕业式但非属灵认证的复盘","id":"youth.10.04","objective":"把自治指向爱和责任。","practice_ids":["youth.review.keep-change-support","youth.review.freedom-for-love"],"review_status":"theology_review","scripture_anchors":["GAL_5_13"],"title":"自由、复盘与服事"}],"review_status":"theology_review","title":"离家前准备、安全与使命"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_08/assets/youth-formation-curriculum.seed.yaml","sha256":"c52f736820a7bd268cb609bbc99c77ac2d3a08de685d658a62769d2fe40ca94b","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer","child_safety_reviewer","accessibility_reviewer"]'::jsonb,'skills-bag-01-12'
