    'ai-formation.batch-08.youth-formation-practice-catalog.seed','08','youth-formation-practice-catalog.seed','1.0.0',
    '3c5f3eba40be299043fa24cdfbd5fb251e80be18d2fa8411338869e1ec59971c','PRODUCT_DEFAULT','theology_review','["13_15","16_18","adult"]'::jsonb,
    '{"catalog_id":"ai-formation.youth-practices.v1","practices":[{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"IDENTITY","full_practice":"比较received self、performed self和真实责任。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.identity.received-not-curated","minimum_action":"写下一项无需展示的价值。","review_status":"theology_review","scripture_anchors":["COL_3_1_4"],"summary":"把线上形象和在基督里领受的身份区分。","title":"身份不等于经营出来的形象"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"IDENTITY","full_practice":"为每个压力找一个真人和一个真理锚点。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.identity.pressure-map","minimum_action":"选择两个最高压力来源。","review_status":"theology_review","scripture_anchors":["ROM_12_2"],"summary":"识别成绩、外貌、关系、家庭和教会形象。","title":"画出身份压力来源"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"IDENTITY","full_practice":"寻求安全、诚实、非强迫的真人对话。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.identity.no-label-rush","minimum_action":"允许自己说“我还在理解”。","review_status":"theology_review","scripture_anchors":["PS_139_13_18"],"summary":"问题和感受不必立即变成完整身份结论。","title":"不急于被标签定义"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"DOUBT","full_practice":"区分事实、经历、情绪和神学问题。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.question.say-it-plainly","minimum_action":"用一句话写出问题。","review_status":"theology_review","scripture_anchors":["MARK_9_24"],"summary":"信仰问题不必伪装成正确答案。","title":"把真实问题说清楚"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"DOUBT","full_practice":"记录仍不确定之处。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.question.source-plan","minimum_action":"选择两个来源类型。","review_status":"theology_review","scripture_anchors":["ACTS_17_11"],"summary":"不同问题需要经文、历史、科学或牧养来源。","title":"为问题选择来源"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"DOUBT","full_practice":"与可信成人约定后续对话。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.question.no-perform","minimum_action":"选择exploring或uncertain。","review_status":"theology_review","scripture_anchors":["JUDE_22"],"summary":"可以暂时不确定而继续敬拜、学习和相交。","title":"不表演确定"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"SEXUALITY","full_practice":"学习同意、求助和安全退出。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.sexuality.body-dignity","minimum_action":"说出一个尊重边界。","review_status":"theology_review","scripture_anchors":["1THESS_4_3_8"],"summary":"拒绝物化、羞辱和强迫。","title":"身体与他人都有尊严"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"SEXUALITY","full_practice":"不在课程系统上传材料。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.sexuality.no-secret-pressure","minimum_action":"记住停止、保存必要信息于安全渠道、求助。","review_status":"theology_review","scripture_anchors":["PS_82_3_4"],"summary":"识别索取影像、勒索和强迫。","title":"秘密、威胁和压力不是爱"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"SEXUALITY","full_practice":"与可信成人讨论，不分享聊天细节。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.sexuality.ai-romance-boundary","minimum_action":"停止一个秘密或性化AI场景。","review_status":"theology_review","scripture_anchors":["HEB_10_24_25"],"summary":"生成的亲密语言不是互惠圣约。","title":"AI浪漫聊天边界"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"SOCIAL_MEDIA","full_practice":"选择一个更诚实的边界。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.social.online-offline-gap","minimum_action":"写一个offline/online gap。","review_status":"theology_review","scripture_anchors":["EPH_4_25"],"summary":"观察自己在展示什么、隐藏什么。","title":"线上形象和真实生活差距"},{"age_bands":["younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"SOCIAL_MEDIA","full_practice":"用运动、朋友、创造或服事替代。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"youth.social.comparison-reset","minimum_action":"暂停一个账号或推荐源。","review_status":"theology_review","scripture_anchors":["GAL_6_4_5"],"su