12"],"summary":"用类别和后果教学。","title":"敏感主题不渲染刺激内容"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"FAMILY_EXTENSION","full_practice":"提供个人或小组替代。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"family-extension.optional","minimum_action":"标记为optional。","review_status":"theology_review","scripture_anchors":["ROM_14_4"],"summary":"家庭能力和安全不同。","title":"家庭延伸不决定课程成绩"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"FAMILY_EXTENSION","full_practice":"改为公开对话和共同规则。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"family-extension.no-surveillance","minimum_action":"删除设备检查任务。","review_status":"theology_review","scripture_anchors":["2COR_8_21"],"summary":"家长不应秘密读取孩子数据。","title":"不布置监控作业"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"OBSERVATION","full_practice":"限制可见范围和保留期限。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"observation.observable-only","minimum_action":"把“他不敬虔”改成具体行为。","review_status":"theology_review","scripture_anchors":["JOHN_7_24"],"summary":"不推断信心、动机或诊断。","title":"教师只记录可观察信号"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"REVIEW","full_practice":"验证版本一致和签署。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"review.separation-of-duty","minimum_action":"配置requiredReviewRoles。","review_status":"theology_review","scripture_anchors":["PROV_11_14"],"summary":"敏感内容需要多角色审核。","title":"作者不能单独批准自己"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"REVIEW","full_practice":"保留审核证据和通知路径。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"review.rollback","minimum_action":"指定rollbackVersion。","review_status":"theology_review","scripture_anchors":["PROV_27_12"],"summary":"错误内容需要快速撤回。","title":"发布必须可回滚"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"REVIEW","full_practice":"在CI执行静态和仓库级验证。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"review.evals","minimum_action":"添加一个负向案例。","review_status":"theology_review","scripture_anchors":["1THESS_5_21"],"summary":"测