    '{"catalog_id":"ai-formation.scenario-controls.v1","practices":[{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORING","full_practice":"确保每个节点服务目标。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.author.learning-goal","minimum_action":"写出一个分辨或行动目标。","review_status":"theology_review","scripture_anchors":["LUKE_6_46_49"],"summary":"情境不是娱乐分支树。","title":"先写情境学习目标"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORING","full_practice":"允许跳过和观察者模式。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.author.fictional-distance","minimum_action":"把人物改成第三人称。","review_status":"theology_review","scripture_anchors":["MATT_7_12"],"summary":"不要求参与者重演真实创伤。","title":"使用虚构距离"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORING","full_practice":"教师卡只保留保护行动。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.author.no-explicit","minimum_action":"删除刺激性细节。","review_status":"theology_review","scripture_anchors":["EPH_5_12"],"summary":"用类别、选择和后果教学。","title":"敏感题材保持非露骨"},{"age_bands":["teacher"],"authority_level":"PASTORAL_WISDOM","domain":"AUTHORING","full_practice":"在debrief中分析而非羞辱。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.author.multiple-plausible","minimum_action":"至少两个选择有可理解动机。","review_status":"theology_review","scripture_anchors":["PROV_18_17"],"summary":"避免把学习变成猜教师答案。","title":"提供多个可理解选择"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"TIMELINE","full_practice":"不要求个人历史。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.timeline.trigger","minimum_action":"选择triggerCategory。","review_status":"theology_review","scripture_anchors":["JAMES_1_14"],"summary":"先看发生了什么。","title":"识别触发"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"TIMELINE","full_practice":"找证据和替代解释。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.timeline.interpretation","minimum_action":"选择两个可能解释。","review_status":"theology_review","scripture_anchors":["PROV_18_13"],"summary":"同一事件可能有多个解释。","title":"区分解释"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"TIMELINE","full_practice":"比较短期承诺和长期果子。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.timeline.desire","minimum_action":"给desired good命名。","review_status":"theology_review","scripture_anchors":["JAMES_4_1_3"],"summary":"看见选择在追求什么。","title":"识别欲望"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"TIMELINE","full_practice":"执行呼吸、移动或离开环境。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.timeline.body","minimum_action":"选择一个身体信号。","review_status":"theology_review","scripture_anchors":["1COR_6_19_20"],"summary":"身体信号提醒需要暂停。","title":"注意身体信号"},{"age_bands":["adult","elementary","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"CHOICE","full_practice":"说明选择理由。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.choice.pause","minimum_action":"等待十秒再选择。","review_status":"theology_review","scripture_anchors":["JAMES_1_19"],"summary":"模拟中也练习停止自动反应。","title":"选择前暂停"},{"age_bands":["adult","elementary","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"CHOICE","full_practice":"说明什么信息需要分享。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.choice.ask-help","minimum_action":"选择一个可信角色。","review_status":"theology_review","scripture_anchors":["PROV_11_14"],"summary":"求助不是失败选项。","title":"把求助作为真实选择"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"CHOICE","full_practice":"包括承认、后果和改变。","guardrails":["不得把操练表现转化为救恩、成熟或价值评分"],"id":"scenario.choice.repair","minimum_action":"选择一个repairPath。","review_status":"theology_review","scripture_anchors":["MATT_5_23_24"],"summary":"错误以后仍有责任行动。","title":"选择修复路径"},{"age_bands":["adult","younger_teen","older_teen"],"authority_level":"PASTORAL_WISDOM","domain":"CONSEQUENCE","full_practice":"标记