n"],"review_status":"theology_review","scripture_anchors":["PROV_15_22"],"title":"替代方案与拒绝权"},{"activity":"Support routing","id":"formation-twin.07.02","objective":"识别工具边界。","practice_ids":["twin.recommendation.ask-human"],"review_status":"theology_review","scripture_anchors":["PROV_11_14"],"title":"转向真人帮助"}],"review_status":"theology_review","title":"建议和人类决定"},{"id":"formation-twin.08","lessons":[{"activity":"Retention policy","id":"formation-twin.08.01","objective":"治理生命周期。","practice_ids":["twin.retention.shortest-useful","twin.retention.minor"],"review_status":"theology_review","scripture_anchors":["MATT_18_5_6"],"title":"最短保留与未成年人保护"},{"activity":"Rights E2E","id":"formation-twin.08.02","objective":"落实数据权利。","practice_ids":["twin.export.owner","twin.delete.transparent"],"review_status":"theology_review","scripture_anchors":["2COR_8_21"],"title":"导出、删除和透明例外"},{"activity":"Copy review","id":"formation-twin.08.03","objective":"建立产品谦卑。","practice_ids":["twin.audit.no-overclaim"],"review_status":"theology_review","scripture_anchors":["1COR_13_9"],"title":"不夸大系统知道什么"}],"review_status":"theology_review","title":"保留、导出、删除与治理"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_11/assets/formation-twin-curriculum.seed.yaml","sha256":"309e4fb7546798e31d9a7769a0a200d6174d0f160cdf257c278448ad854a7606","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
