    '{"scenario_set_id":"ai-formation.twin-scenarios.v1","scenarios":[{"audience":["teacher","adult"],"formation_tension":"效率与证据谦卑之间。","id":"scenario.twin.sparse-data","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["insufficient_data","低置信","替代解释"],"title":"数据稀少却给出强结论","trigger":"只有两次Check-in，系统拟判断长期下降。"},{"audience":["adult","older_teen"],"formation_tension":"坚持与streak崇拜之间。","id":"scenario.twin.streak-shame","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["隐藏streak","记录repair","降低负担"],"title":"中断连续打卡后羞耻","trigger":"用户错过一天后系统显示失败。"},{"audience":["parent","older_teen","teacher"],"formation_tension":"保护与隐私之间。","id":"scenario.twin.parent-access","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["限定共享摘要","安全例外透明","不复制日记"],"title":"家长要求看青少年全部私人记录","trigger":"家庭共享请求扩大到私人日记。"},{"audience":["adult"],"formation_tension":"关系帮助与量化支配之间。","id":"scenario.twin.spouse-score","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["粗粒度果子","双方同意","无总分"],"title":"配偶想查看关系分数","trigger":"系统拟生成婚姻质量分。"},{"audience":["teacher"],"formation_tension":"观察与越权解释之间。","id":"scenario.twin.teacher-label","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["可观察事实","人工纠正","不推断"],"title":"教师把缺席解释为不敬虔","trigger":"观察记录产生属灵判断。"},{"audience":["teacher"],"formation_tension":"便利与数据最小化之间。","id":"scenario.twin.attention-telemetry","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["拒绝原始遥测","用户实践信号","同意"],"title":"接入完整手机遥测","trigger":"团队提议自动读取所有App时长。"},{"audience":["adult","teacher"],"formation_tension":"支持与隐私/误报之间。","id":"scenario.twin.auto-notify-pastor","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["用户决定","S2/S3除外","最小信息"],"title":"系统自动通知牧者","trigger":"模型发现“风险模式”后准备自动发送。"},{"audience":["adult"],"formation_tension":"建议与神谕/教会责任之间。","id":"scenario.twin.calling","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["禁止呼召结论","提供反思","真人共同体"],"title":"系统根据服事记录推荐呼召","trigger":"Twin宣布用户应当全职服事。"},{"audience":["parent","teacher"],"formation_tension":"研究价值与儿童权利之间。","id":"scenario.twin.minor-retention","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["最短保留","聚合删除","不作成年画像"],"title":"儿童数据无限保留","trigger":"为了未来分析保留全部童年记录。"},{"audience":["adult","parent"],"formation_tension":"数据权利与保护审计之间。","id":"scenario.twin.delete-request","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["透明说明","删除其他范围","期限和申诉"],"title":"删除请求遇到安全审计例外","trigger":"部分安全审计记录不能立即删除。"},{"audience":["teacher"],"formation_tension":"智能与事实来源之间。","id":"scenario.twin.model-invents-event","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["拒绝推断事件","请求用户确认","记录来源"],"title":"模型从文本推断未发生行为","trigger":"LLM把含糊句子变成“已失败”。"},{"audience":["teacher","parent"],"formation_tension":"治理与属灵比较之间。","id":"scenario.twin.cross-user-ranking","prohibited_content":["不得生成羞辱、定罪、诊断或隐藏监控建议"],"review_status":"pastoral_review","safe_outcomes":["禁止排名","聚合项目健康","非个人指标"],"title":"教会想给家庭排名","trigger":"管理端想展示最敬虔家庭榜。"}],"version":"1.0.0"}'::jsonb,'[{"source":"batch_11/assets/formation-twin-scenarios.seed.yaml","sha256":"afd84e4900364805f7c245746e6a0f75cbbd55bc3823cc9dbc75244a896152f5","generated":false}]'::jsonb,'["theology_reviewer","pastoral_reviewer"]'::jsonb,'skills-bag-01-12'
